# 21_fig5_figure.R: Figure 5 (shared EPA pool) and full-pool sensitivity; supplementary response curves for TN, Chl-a and geographic distance. Plotted values: tables/fig5_plotted_values_<pool>.csv
source("common.R"); RL <- c(incidence = "Incidence", relative = "Relative abundance"); PRED <- c(TP = "TP", TN = "TN", Chla = "Chl-a", distance = "Geographic distance"); PCOL <- c(TP = pal[["petrol"]], TN = pal[["orange"]], `Chl-a` = pal[["sage"]], `Geographic distance` = pal[["grey"]])
panel_lab <- function(community, response) factor(paste(sub("EPA ", "", community), RL[response], sep = "\n"), c("macroinvertebrates\nIncidence", "macroinvertebrates\nRelative abundance", "zooplankton\nIncidence", "zooplankton\nRelative abundance"))
build5 <- function(pool) {
  V <- read.csv(sprintf("tables/fig5_validation_folds_%s.csv", pool)); I <- read.csv(sprintf("tables/fig5_importance_folds_%s.csv", pool)); Cv <- read.csv(sprintf("tables/fig5_response_curves_%s.csv", pool))
  # importance: per fold (mean over seeds), then mean and fold range
  Ip <- I |> group_by(community, order, response, fold, predictor, component) |> summarise(absolute = mean(absolute, na.rm = TRUE), D2 = mean(D2_heldout), .groups = "drop") |> mutate(absolute = ifelse(is.nan(absolute), NA, absolute)) |>
    group_by(community, order, response, predictor, component) |> summarise(abs_mean = mean(absolute, na.rm = TRUE), abs_lo = suppressWarnings(min(absolute, na.rm = TRUE)), abs_hi = suppressWarnings(max(absolute, na.rm = TRUE)), heldout_D2 = mean(D2), n_valid_folds = sum(!is.na(absolute)), .groups = "drop") |> mutate(across(c(abs_mean, abs_lo, abs_hi), ~ ifelse(is.finite(.), ., NA)), rel = ifelse(heldout_D2 >= .02, abs_mean / heldout_D2, NA))
  Ip$term <- ifelse(Ip$component == "distance", "Distance", ifelse(Ip$component == "spread", "Spread", "Position")); Ip$pred <- factor(PRED[Ip$predictor], PRED); Ip$panel <- panel_lab(Ip$community, Ip$response)
  th5 <- th() + theme(legend.position = "bottom", legend.box = "horizontal", panel.spacing = unit(3, "mm"), strip.text = element_text(size = 6)); xo <- scale_x_continuous(breaks = c(2, 3, 4, 5, 6, 8, 10, 12))
  base <- function(y, lab) ggplot(Ip, aes(order, .data[[y]], colour = pred, linetype = term, group = interaction(pred, term))) + geom_hline(yintercept = 0, linewidth = .3, colour = "grey70") + geom_line(linewidth = .5) + geom_point(size = .8) + facet_grid(~panel, scales = "free_x") + xo + scale_colour_manual(values = PCOL, name = NULL) + scale_linetype_manual(values = c(Spread = 1, Position = 2, Distance = 1), name = NULL) + labs(x = "Zeta order k", y = lab) + th5
  A <- base("abs_mean", expression("Held-out absolute contribution (" * Delta * D^2 * ")")); B <- base("rel", expression("Relative importance (share of held-out " * D^2 * ", where " * D^2 >= 0.02 * ")")) + coord_cartesian(ylim = c(-1, 1.5))
  # response curves TP
  Cc <- Cv |> filter(quantity == "curve", predictor == "TP") |> mutate(panel = panel_lab(community, response), axis = factor(axis, c("spread", "position"), c("TP spread", "TP position")), ord = factor(order)); Cc <- Cc |> filter(order %in% c(2, 5))
  C <- ggplot(Cc, aes(x, colour = ord)) + geom_line(aes(y = predicted), linewidth = .6) + geom_point(aes(y = observed), size = .8, shape = 1) + facet_grid(axis ~ panel, scales = "free") + scale_colour_manual(values = c(`2` = pal[["petrol"]], `5` = pal[["orange"]]), name = "Order k") + labs(x = expression(log[10] ~ "TP"), y = "Dissimilarity: fitted (lines), observed bin mean (circles)") + th5
  # deviance
  Dv <- V |> group_by(community, order, response, model, fold) |> summarise(D2 = mean(D2_heldout, na.rm = TRUE), tr = mean(D2_train, na.rm = TRUE), .groups = "drop") |> group_by(community, order, response, model) |> summarise(heldout = median(D2), lo = min(D2), hi = max(D2), train = mean(tr), .groups = "drop") |> mutate(train = ifelse(is.nan(train), NA, train), panel = panel_lab(community, response), model = factor(model, c("spread_only", "linear_const", "nonlinear_const"), c("Spread only", "Spread + linear position", "Spread + nonlinear position")))
  D <- ggplot(Dv, aes(order, heldout, colour = model)) + geom_hline(yintercept = 0, linewidth = .3, colour = "grey70") + geom_linerange(aes(ymin = lo, ymax = hi), linewidth = .3, alpha = .4, position = position_dodge(.35)) + geom_line(linewidth = .5, position = position_dodge(.35)) + geom_point(size = .8, position = position_dodge(.35)) +
    geom_line(data = Dv |> filter(model == "Spread + linear position"), aes(y = train, linetype = "Training (all blocks)"), colour = "black", linewidth = .4) + scale_linetype_manual(values = 3, name = NULL) + facet_grid(~panel, scales = "free_x") + xo + scale_colour_manual(values = c(pal[["grey"]], pal[["petrol"]], pal[["orange"]]), name = NULL) + labs(x = "Zeta order k", y = expression("Held-out spatial-block " * D^2 * " (median, fold range)")) + th5
  fig <- (A / B / C / D) + plot_layout(heights = c(1, 1, 1.6, 1)) + plot_annotation(tag_levels = "A") & theme(plot.tag = element_text(face = "bold", size = 9))
  list(fig = fig, vals = list(importance = Ip, validation = Dv, curves = Cc, curves_all = Cv)) }
for (pool in c("shared", "full")) { r <- build5(pool); sv(r$fig, if (pool == "shared") "Figure5_main" else "FigureS5_full_pool_sensitivity", 7.4, 10.5); write.csv(r$vals$importance, sprintf("tables/fig5_plotted_importance_%s.csv", pool), row.names = FALSE); write.csv(r$vals$validation, sprintf("tables/fig5_plotted_validation_%s.csv", pool), row.names = FALSE); write.csv(r$vals$curves_all, sprintf("tables/fig5_plotted_response_curves_%s.csv", pool), row.names = FALSE) }
# ---- S5.1: response curves for the other predictors (shared pool)
Cv <- read.csv("tables/fig5_response_curves_shared.csv") |> filter(quantity == "curve", predictor != "TP", order %in% c(2, 5)) |> mutate(panel = panel_lab(community, response), pred = factor(PRED[predictor], PRED), axis = factor(axis, c("spread", "position"), c("Spread", "Position")), ord = factor(order))
pS <- ggplot(Cv, aes(x, colour = ord)) + geom_line(aes(y = predicted), linewidth = .6) + geom_point(aes(y = observed), size = .8, shape = 1) + facet_grid(pred + axis ~ panel, scales = "free") + scale_colour_manual(values = c(`2` = pal[["petrol"]], `5` = pal[["orange"]]), name = "Order k") + labs(x = "Predictor value (log10 scale for TN and Chl-a; km for distance spread)", y = "Dissimilarity: fitted (lines), observed bin mean (circles)") + th(6) + theme(legend.position = "bottom", strip.text.y = element_text(size = 5))
sv(pS, "FigureS5_1_response_curves_other_predictors", 7.4, 10.5); cat("fig5 done\n")
